const __pageData = JSON.parse('{"title":"Pam Bondi","description":"","frontmatter":{"title":"Pam Bondi","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["attorney-general","doj","appointments"],"sources":["raw/badlands-brief-094.md","raw/badlands-brief-144.md","raw/badlands-brief-174.md","raw/badlands-brief-1cd.md","raw/badlands-brief-245.md","raw/badlands-brief-405.md","raw/badlands-brief-4ec.md","raw/badlands-brief-40d.md","raw/badlands-brief-509.md","raw/badlands-brief-733.md","raw/badlands-brief-8db.md","raw/badlands-brief-c07.md","raw/badlands-brief-c2d.md","raw/badlands-brief-d3b.md","raw/badlands-brief-e3f.md","raw/badlands-news-brief-09b.md","raw/badlands-news-brief-144.md","raw/badlands-news-brief-1a7.md","raw/badlands-news-brief-201.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-243.md","raw/badlands-news-brief-26f.md","raw/badlands-news-brief-351.md","raw/badlands-news-brief-426.md","raw/badlands-news-brief-448.md","raw/badlands-news-brief-4a9.md","raw/badlands-news-brief-58e.md","raw/badlands-news-brief-5d1.md","raw/badlands-news-brief-5c8.md","raw/badlands-news-brief-6af.md","raw/badlands-news-brief-71c.md","raw/badlands-news-brief-721.md","raw/badlands-news-brief-656.md","raw/badlands-news-brief-752.md","raw/badlands-news-brief-762.md","raw/badlands-news-brief-795.md","raw/badlands-news-brief-7bb.md","raw/badlands-news-brief-899.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/pam-bondi.md","filePath":"entities/pam-bondi.md","lastUpdated":null}');
